'use strict';
const CACHE='yanxi-spelling-v1',ROOT=new URL('./',self.location.href);
const SHELL=['./','latest.html','style.css?v=1','core.js?v=1','app.js?v=1','data.json','manifest.json','icon.svg','icon-192.png','icon-512.png','touch-icon.png','licenses/ATTRIBUTION.txt','licenses/NETEM.txt','licenses/ECDICT.txt','licenses/cmudict.txt'].map(p=>new URL(p,ROOT).href);
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);try{await Promise.all(SHELL.map(async url=>{const response=await fetch(new Request(url,{cache:'reload',credentials:'same-origin',redirect:'error'}));if(!response.ok)throw Error('Incomplete offline book');await cache.put(url,response);}));await self.skipWaiting();}catch(error){await caches.delete(CACHE);throw error;}})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{await Promise.all((await caches.keys()).filter(k=>k.startsWith('yanxi-spelling-')&&k!==CACHE).map(k=>caches.delete(k)));await self.clients.claim();})()));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==ROOT.origin||!url.pathname.startsWith(ROOT.pathname))return;const home=event.request.mode==='navigate'&&[ROOT.pathname,ROOT.pathname+'index.html',ROOT.pathname+'latest.html'].includes(url.pathname);if(!home&&!SHELL.includes(url.href))return;event.respondWith((async()=>{const cache=await caches.open(CACHE),saved=await cache.match(home?ROOT.href:event.request);if(home){try{const fresh=await fetch(event.request);if(fresh.ok&&(await fresh.clone().text()).includes('词芽')){await cache.put(ROOT.href,fresh.clone());return fresh;}}catch(_){}if(saved)return saved;throw Error('Book not yet saved');}return saved||fetch(event.request);})());});
self.addEventListener('message',event=>{if(event.data?.type!=='CIYA_OFFLINE_STATUS'||!event.ports[0])return;event.waitUntil((async()=>{try{const cache=await caches.open(CACHE),items=await Promise.all(SHELL.map(url=>cache.match(url)));event.ports[0].postMessage({ready:items.every(Boolean),version:CACHE});}catch(_){event.ports[0].postMessage({ready:false});}})());});
